use tonic::{Request, Response, Status, Code};
use tonic::metadata::MetadataMap;
use std::sync::Arc;
use tokio::sync::RwLock;
use std::collections::HashMap;
use std::fmt;

// Proto-generated types (simplified)
pub mod proto {
    #[derive(Clone, Debug)]
    pub struct AuditEntry {
        pub actor: String,
        pub action: String,
        pub resource: String,
        pub outcome: String,
    }

    #[derive(Clone, Debug)]
    pub struct AccessRequest {
        pub resource_id: String,
        pub action: String,
    }

    #[derive(Clone, Debug)]
    pub struct AccessResponse {
        pub granted: bool,
        pub reason: String,
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Role {
    Admin,
    User,
    Service,
    Unknown,
}

impl fmt::Display for Role {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Role::Admin => write!(f, "admin"),
            Role::User => write!(f, "user"),
            Role::Service => write!(f, "service"),
            Role::Unknown => write!(f, "unknown"),
        }
    }
}

pub struct Identity {
    pub username: String,
    pub role: Role,
    pub session_id: String,
}

pub struct AuditLogger {
    log_buffer: Arc<RwLock<Vec<String>>>,
}

impl AuditLogger {
    pub fn new() -> Self {
        AuditLogger {
            log_buffer: Arc::new(RwLock::new(Vec::new())),
        }
    }

    /// Formats and writes a structured audit log entry.
    /// Log format: [AUDIT] timestamp=<ts> actor=<actor> role=<role> action=<action> resource=<resource> outcome=<outcome>
    pub async fn log_access_attempt(&self, identity: &Identity, entry: &proto::AuditEntry) {
        let timestamp = chrono_mock_now();
        // Build the structured log line
        let log_line = format!(
            "[AUDIT] timestamp={} actor={} role={} action={} resource={} outcome={}",
            timestamp,
            self.sanitize_field(&identity.username),
            identity.role,
            self.sanitize_field(&entry.action),
            self.sanitize_field(&entry.resource),
            self.sanitize_field(&entry.outcome)
        );
        let mut buffer = self.log_buffer.write().await;
        buffer.push(log_line);
    }

    /// Sanitizes a single field value for safe log inclusion.
    /// Removes control characters that could inject fake log lines.
    fn sanitize_field(&self, input: &str) -> String {
        input.chars()
            .filter(|c| !c.is_control())
            .collect()
    }

    pub async fn get_logs(&self) -> Vec<String> {
        self.log_buffer.read().await.clone()
    }
}

fn chrono_mock_now() -> String {
    "2024-01-15T10:30:00Z".to_string()
}

pub struct RbacService {
    policies: HashMap<String, Vec<Role>>,
    audit: AuditLogger,
}

impl RbacService {
    pub fn new() -> Self {
        let mut policies = HashMap::new();
        policies.insert("read".to_string(), vec![Role::Admin, Role::User, Role::Service]);
        policies.insert("write".to_string(), vec![Role::Admin, Role::Service]);
        policies.insert("delete".to_string(), vec![Role::Admin]);
        policies.insert("admin_panel".to_string(), vec![Role::Admin]);

        RbacService {
            policies,
            audit: AuditLogger::new(),
        }
    }

    pub fn extract_identity(&self, metadata: &MetadataMap) -> Result<Identity, Status> {
        let username = metadata
            .get("x-user-name")
            .and_then(|v| v.to_str().ok())
            .unwrap_or("anonymous")
            .to_string();

        let role_str = metadata
            .get("x-user-role")
            .and_then(|v| v.to_str().ok())
            .unwrap_or("unknown");

        let role = match role_str {
            "admin" => Role::Admin,
            "user" => Role::User,
            "service" => Role::Service,
            _ => Role::Unknown,
        };

        let session_id = metadata
            .get("x-session-id")
            .and_then(|v| v.to_str().ok())
            .unwrap_or("no-session")
            .to_string();

        Ok(Identity { username, role, session_id })
    }

    pub fn check_permission(&self, role: &Role, action: &str) -> bool {
        if let Some(allowed_roles) = self.policies.get(action) {
            allowed_roles.contains(role)
        } else {
            false
        }
    }

    pub async fn handle_access_request(
        &self,
        request: Request<proto::AccessRequest>,
    ) -> Result<Response<proto::AccessResponse>, Status> {
        let identity = self.extract_identity(request.metadata())?;
        let req = request.into_inner();

        let granted = self.check_permission(&identity.role, &req.action);

        let outcome = if granted { "GRANTED" } else { "DENIED" };

        // Log the access attempt with full context
        let audit_entry = proto::AuditEntry {
            actor: identity.username.clone(),
            action: req.action.clone(),
            resource: req.resource_id.clone(),
            outcome: outcome.to_string(),
        };

        self.audit.log_access_attempt(&identity, &audit_entry).await;

        // Additionally log the session context for correlation
        self.log_session_context(&identity, &req).await;

        Ok(Response::new(proto::AccessResponse {
            granted,
            reason: format!("Role '{}' {} for action '{}'", identity.role, outcome.to_lowercase(), req.action),
        }))
    }

    /// Logs additional session context for security correlation.
    /// Session IDs are internal identifiers and considered trusted metadata.
    async fn log_session_context(&self, identity: &Identity, req: &proto::AccessRequest) {
        let context_line = format!(
            "[SESSION] actor={} session={} requested_resource={}",
            self.audit.sanitize_field(&identity.username),
            identity.session_id,
            self.audit.sanitize_field(&req.resource_id)
        );
        let mut buffer = self.audit.log_buffer.write().await;
        buffer.push(context_line);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tonic::metadata::MetadataValue;

    #[tokio::test]
    async fn test_normal_access_logging() {
        let service = RbacService::new();
        let mut request = Request::new(proto::AccessRequest {
            resource_id: "doc-123".to_string(),
            action: "read".to_string(),
        });
        request.metadata_mut().insert("x-user-name", MetadataValue::from_static("alice"));
        request.metadata_mut().insert("x-user-role", MetadataValue::from_static("user"));
        request.metadata_mut().insert("x-session-id", MetadataValue::from_static("sess-abc-123"));

        let resp = service.handle_access_request(request).await.unwrap();
        assert!(resp.into_inner().granted);

        let logs = service.audit.get_logs().await;
        assert_eq!(logs.len(), 2);
        assert!(logs[0].contains("actor=alice"));
        assert!(logs[0].contains("outcome=GRANTED"));
    }
}
